WITH filtered_customers AS (SELECT * FROM customers WHERE NOT (UPPER(email) LIKE '%LIC%' AND is_active AND credit_limit >= 10700)), CountryGroupSummary AS (SELECT CASE WHEN country IN ('DE', 'SG') THEN 'core' ELSE 'other' END country_group, CASE WHEN city IN ('London', 'New York') THEN 'priority' ELSE 'other' END city_group, COUNT(credit_limit) credit_limit_count, MAX(age) max_age FROM filtered_customers GROUP BY CASE WHEN country IN ('DE', 'SG') THEN 'core' ELSE 'other' END, CASE WHEN city IN ('London', 'New York') THEN 'priority' ELSE 'other' END) SELECT * FROM CountryGroupSummary WHERE credit_limit_count > 5 ORDER BY country_group, city_group LIMIT 50;
